FILES = {'buster/experience/__init__.py': '"""\nBuster v3.8 Experience Engine.\n\nMemory remembers facts.\nLearning remembers what happened.\nExperience turns repeated outcomes into engineering judgement.\n"""\nfrom .engine import ExperienceEngine\nfrom .records import ExperienceRecord, make_experience_record\nfrom .skills import SkillProfile, SkillEngine\nfrom .design_decisions import DesignDecisionStore\nfrom .project_experience import ProjectExperienceIndex\nfrom .user_overrides import UserOverrideStore\n\n__all__ = [\n    "ExperienceEngine", "ExperienceRecord", "make_experience_record",\n    "SkillProfile", "SkillEngine", "DesignDecisionStore",\n    "ProjectExperienceIndex", "UserOverrideStore",\n]\n', 'buster/experience/storage.py': 'from __future__ import annotations\nimport json\nfrom pathlib import Path\nfrom typing import Any, Dict, List\n\ndef ensure_parent(path: Path) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n\ndef load_json(path: Path, default: Any) -> Any:\n    ensure_parent(path)\n    if not path.exists():\n        save_json(path, default)\n        return default\n    try:\n        text = path.read_text(encoding="utf-8").strip()\n        return json.loads(text) if text else default\n    except Exception:\n        return default\n\ndef save_json(path: Path, data: Any) -> None:\n    ensure_parent(path)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")\n\ndef append_json_list(path: Path, item: Dict[str, Any]) -> List[Dict[str, Any]]:\n    data = load_json(path, [])\n    if not isinstance(data, list):\n        data = []\n    data.append(item)\n    save_json(path, data)\n    return data\n', 'buster/experience/records.py': 'from __future__ import annotations\nfrom dataclasses import dataclass, asdict, field\nfrom datetime import datetime\nfrom typing import Any, Dict, List\nimport uuid\n\ndef _now() -> str:\n    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"\n\n@dataclass\nclass ExperienceRecord:\n    """A durable record of an engineering outcome."""\n    id: str\n    timestamp: str\n    project: str\n    project_type: str\n    task: str\n    strategy: str\n    outcome: str\n    confidence: float = 0.5\n    risk: str = "medium"\n    tools: List[str] = field(default_factory=list)\n    agents: List[str] = field(default_factory=list)\n    plugins: List[str] = field(default_factory=list)\n    errors: List[str] = field(default_factory=list)\n    fixes: List[str] = field(default_factory=list)\n    design_choices: List[str] = field(default_factory=list)\n    user_feedback: str = ""\n    notes: str = ""\n    metadata: Dict[str, Any] = field(default_factory=dict)\n\n    @property\n    def success(self) -> bool:\n        return self.outcome.lower() in {"success", "passed", "fixed", "accepted", "completed"}\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> "ExperienceRecord":\n        return cls(\n            id=data.get("id") or str(uuid.uuid4()),\n            timestamp=data.get("timestamp") or _now(),\n            project=data.get("project", "default"),\n            project_type=data.get("project_type", "general"),\n            task=data.get("task", "unknown"),\n            strategy=data.get("strategy", "default"),\n            outcome=data.get("outcome", "unknown"),\n            confidence=float(data.get("confidence", 0.5)),\n            risk=data.get("risk", "medium"),\n            tools=list(data.get("tools", [])),\n            agents=list(data.get("agents", [])),\n            plugins=list(data.get("plugins", [])),\n            errors=list(data.get("errors", [])),\n            fixes=list(data.get("fixes", [])),\n            design_choices=list(data.get("design_choices", [])),\n            user_feedback=data.get("user_feedback", ""),\n            notes=data.get("notes", ""),\n            metadata=dict(data.get("metadata", {})),\n        )\n\ndef make_experience_record(project: str, project_type: str, task: str, strategy: str, outcome: str, **kwargs: Any) -> ExperienceRecord:\n    return ExperienceRecord(id=str(uuid.uuid4()), timestamp=_now(), project=project, project_type=project_type, task=task, strategy=strategy, outcome=outcome, **kwargs)\n', 'buster/experience/skills.py': 'from __future__ import annotations\nfrom dataclasses import dataclass, asdict\nfrom pathlib import Path\nfrom typing import Dict, Any, List\nfrom .storage import load_json, save_json\n\n@dataclass\nclass SkillProfile:\n    name: str\n    level: int = 1\n    confidence: float = 0.50\n    successes: int = 0\n    failures: int = 0\n    last_used: str = ""\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n    @classmethod\n    def from_dict(cls, data: Dict[str, Any]) -> "SkillProfile":\n        return cls(name=data.get("name", "general"), level=int(data.get("level", 1)), confidence=float(data.get("confidence", 0.50)), successes=int(data.get("successes", 0)), failures=int(data.get("failures", 0)), last_used=data.get("last_used", ""))\n\nclass SkillEngine:\n    """Tracks Buster\'s skill growth by project type and tool domain."""\n    def __init__(self, path: str | Path = "data/skill_profiles.json") -> None:\n        self.path = Path(path)\n        raw = load_json(self.path, {})\n        self.skills: Dict[str, SkillProfile] = {name: SkillProfile.from_dict(value) for name, value in raw.items()} if isinstance(raw, dict) else {}\n    def get(self, name: str) -> SkillProfile:\n        key = (name or "general").lower().strip()\n        if key not in self.skills:\n            self.skills[key] = SkillProfile(name=key)\n            self.save()\n        return self.skills[key]\n    def update(self, name: str, success: bool, timestamp: str = "") -> SkillProfile:\n        skill = self.get(name)\n        if success: skill.successes += 1\n        else: skill.failures += 1\n        total = max(1, skill.successes + skill.failures)\n        skill.confidence = round(0.35 + 0.65 * (skill.successes / total), 3)\n        skill.level = max(1, min(5, 1 + (skill.successes // 3)))\n        skill.last_used = timestamp or skill.last_used\n        self.save()\n        return skill\n    def top_skills(self, limit: int = 5) -> List[SkillProfile]:\n        return sorted(self.skills.values(), key=lambda s: (s.level, s.confidence, s.successes), reverse=True)[:limit]\n    def save(self) -> None:\n        save_json(self.path, {name: profile.to_dict() for name, profile in self.skills.items()})\n', 'buster/experience/design_decisions.py': 'from __future__ import annotations\nfrom pathlib import Path\nfrom typing import Any, Dict, List\nfrom datetime import datetime\nfrom .storage import load_json, save_json\n\ndef _now() -> str:\n    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"\n\nclass DesignDecisionStore:\n    """Stores architecture/design choices and ranks how well they work."""\n    def __init__(self, path: str | Path = "data/design_decisions.json") -> None:\n        self.path = Path(path)\n        data = load_json(self.path, [])\n        self.decisions: List[Dict[str, Any]] = data if isinstance(data, list) else []\n    def record(self, project_type: str, decision: str, outcome: str, confidence: float = 0.5, notes: str = "") -> Dict[str, Any]:\n        item = {"timestamp": _now(), "project_type": project_type or "general", "decision": decision, "outcome": outcome, "confidence": float(confidence), "notes": notes}\n        self.decisions.append(item); self.save(); return item\n    def recommend(self, project_type: str, limit: int = 5) -> List[Dict[str, Any]]:\n        ptype = (project_type or "general").lower()\n        candidates = [d for d in self.decisions if d.get("project_type", "").lower() in {ptype, "general"}]\n        def score(d: Dict[str, Any]) -> float:\n            bonus = 1.0 if str(d.get("outcome", "")).lower() in {"success", "accepted", "passed"} else 0.0\n            return float(d.get("confidence", 0.5)) + bonus\n        return sorted(candidates, key=score, reverse=True)[:limit]\n    def save(self) -> None:\n        save_json(self.path, self.decisions)\n', 'buster/experience/project_experience.py': 'from __future__ import annotations\nfrom pathlib import Path\nfrom typing import Dict, Any\nfrom .records import ExperienceRecord\nfrom .storage import load_json, save_json\n\nclass ProjectExperienceIndex:\n    """Indexes experience by project and project type."""\n    def __init__(self, path: str | Path = "data/project_experience_index.json") -> None:\n        self.path = Path(path)\n        data = load_json(self.path, {"projects": {}, "types": {}})\n        self.data = data if isinstance(data, dict) else {"projects": {}, "types": {}}\n        self.data.setdefault("projects", {}); self.data.setdefault("types", {})\n    def add(self, record: ExperienceRecord) -> None:\n        for section, key in (("projects", record.project), ("types", record.project_type)):\n            bucket = self.data[section].setdefault(key or "default", {"total": 0, "successes": 0, "failures": 0, "strategies": {}, "last_seen": ""})\n            bucket["total"] += 1\n            if record.success: bucket["successes"] += 1\n            else: bucket["failures"] += 1\n            bucket["last_seen"] = record.timestamp\n            strat = bucket["strategies"].setdefault(record.strategy, {"successes": 0, "failures": 0})\n            if record.success: strat["successes"] += 1\n            else: strat["failures"] += 1\n        self.save()\n    def summary_for_type(self, project_type: str) -> Dict[str, Any]:\n        return self.data.get("types", {}).get(project_type or "general", {})\n    def best_strategy(self, project_type: str) -> str:\n        summary = self.summary_for_type(project_type)\n        strategies = summary.get("strategies", {}) if isinstance(summary, dict) else {}\n        best, best_score = "default", -1.0\n        for name, stats in strategies.items():\n            total = max(1, stats.get("successes", 0) + stats.get("failures", 0))\n            score = stats.get("successes", 0) / total\n            if score > best_score: best, best_score = name, score\n        return best\n    def save(self) -> None:\n        save_json(self.path, self.data)\n', 'buster/experience/user_overrides.py': 'from __future__ import annotations\nfrom pathlib import Path\nfrom typing import Any, Dict, List\nfrom datetime import datetime\nfrom .storage import load_json, save_json\n\ndef _now() -> str:\n    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"\n\nclass UserOverrideStore:\n    """Remembers when the user chooses a different path than Buster recommended."""\n    def __init__(self, path: str | Path = "data/user_overrides.json") -> None:\n        self.path = Path(path)\n        data = load_json(self.path, [])\n        self.overrides: List[Dict[str, Any]] = data if isinstance(data, list) else []\n    def record(self, context: str, recommended: str, chosen: str, reason: str = "") -> Dict[str, Any]:\n        item = {"timestamp": _now(), "context": context, "recommended": recommended, "chosen": chosen, "reason": reason}\n        self.overrides.append(item); self.save(); return item\n    def recent(self, limit: int = 10) -> List[Dict[str, Any]]:\n        return list(reversed(self.overrides[-limit:]))\n    def save(self) -> None:\n        save_json(self.path, self.overrides)\n', 'buster/experience/engine.py': 'from __future__ import annotations\nfrom pathlib import Path\nfrom typing import Any, Dict, List\nfrom .records import ExperienceRecord, make_experience_record\nfrom .storage import load_json, save_json\nfrom .skills import SkillEngine\nfrom .design_decisions import DesignDecisionStore\nfrom .project_experience import ProjectExperienceIndex\nfrom .user_overrides import UserOverrideStore\n\nclass ExperienceEngine:\n    """Coordinates Buster\'s engineering experience layer."""\n    def __init__(self, data_dir: str | Path = "data") -> None:\n        self.data_dir = Path(data_dir)\n        self.memory_path = self.data_dir / "experience_memory.json"\n        self.records: List[Dict[str, Any]] = load_json(self.memory_path, [])\n        if not isinstance(self.records, list): self.records = []\n        self.skills = SkillEngine(self.data_dir / "skill_profiles.json")\n        self.decisions = DesignDecisionStore(self.data_dir / "design_decisions.json")\n        self.projects = ProjectExperienceIndex(self.data_dir / "project_experience_index.json")\n        self.overrides = UserOverrideStore(self.data_dir / "user_overrides.json")\n    def record_outcome(self, record: ExperienceRecord | Dict[str, Any]) -> ExperienceRecord:\n        if isinstance(record, dict): record = ExperienceRecord.from_dict(record)\n        self.records.append(record.to_dict())\n        save_json(self.memory_path, self.records)\n        self.skills.update(record.project_type, record.success, record.timestamp)\n        self.projects.add(record)\n        for choice in record.design_choices:\n            self.decisions.record(record.project_type, choice, record.outcome, record.confidence)\n        return record\n    def record_simple(self, project: str, project_type: str, task: str, strategy: str, outcome: str, **kwargs: Any) -> ExperienceRecord:\n        return self.record_outcome(make_experience_record(project, project_type, task, strategy, outcome, **kwargs))\n    def recommend_for_project(self, project_type: str, task: str = "") -> Dict[str, Any]:\n        skill = self.skills.get(project_type)\n        best_strategy = self.projects.best_strategy(project_type)\n        designs = self.decisions.recommend(project_type)\n        confidence = min(0.99, max(0.35, skill.confidence + (0.05 if best_strategy != "default" else 0.0)))\n        return {"project_type": project_type or "general", "task": task, "recommended_strategy": best_strategy, "confidence": round(confidence, 3), "skill": skill.to_dict(), "recommended_designs": designs, "recent_overrides": self.overrides.recent(5)}\n    def summary(self) -> Dict[str, Any]:\n        successes = sum(1 for r in self.records if str(r.get("outcome", "")).lower() in {"success", "passed", "fixed", "accepted", "completed"})\n        total = len(self.records)\n        return {"records": total, "successes": successes, "failures": total - successes, "success_rate": round(successes / total, 3) if total else 0.0, "top_skills": [s.to_dict() for s in self.skills.top_skills(5)]}\n', 'buster/intelligence/experience_advisor.py': 'from __future__ import annotations\nfrom typing import Any, Dict\ntry:\n    from buster.experience.engine import ExperienceEngine\nexcept Exception:\n    ExperienceEngine = None  # type: ignore\n\nclass ExperienceAdvisor:\n    """Feeds Experience Engine recommendations into the Intelligence Core."""\n    def __init__(self, data_dir: str = "data") -> None:\n        self.data_dir = data_dir\n        self.engine = ExperienceEngine(data_dir) if ExperienceEngine else None\n    def advise(self, project_type: str, task: str = "") -> Dict[str, Any]:\n        if not self.engine:\n            return {"project_type": project_type, "task": task, "recommended_strategy": "default", "confidence": 0.5, "reason": "Experience Engine unavailable"}\n        rec = self.engine.recommend_for_project(project_type, task)\n        rec["reason"] = "Based on previous Buster engineering outcomes."\n        return rec\n', 'buster/brain/planner/experience_planner.py': 'from __future__ import annotations\nfrom typing import Any, Dict\ntry:\n    from buster.intelligence.experience_advisor import ExperienceAdvisor\nexcept Exception:\n    ExperienceAdvisor = None  # type: ignore\n\nclass ExperiencePlanner:\n    """Creates safer execution hints using past project experience."""\n    def __init__(self, data_dir: str = "data") -> None:\n        self.advisor = ExperienceAdvisor(data_dir) if ExperienceAdvisor else None\n    def plan_with_experience(self, project_type: str, task: str) -> Dict[str, Any]:\n        if not self.advisor:\n            return {"steps": ["plan", "execute", "verify"], "confidence": 0.5}\n        advice = self.advisor.advise(project_type, task)\n        strategy = advice.get("recommended_strategy") or "default"\n        steps = ["inspect_project", "select_strategy"]\n        steps.append(f"apply_strategy:{strategy}" if strategy != "default" else "use_default_strategy")\n        steps.extend(["run_agents", "verify_result", "record_experience"])\n        return {"project_type": project_type, "task": task, "strategy": strategy, "confidence": advice.get("confidence", 0.5), "steps": steps, "advice": advice}\n', 'buster/workspace/experience_dashboard.py': 'from __future__ import annotations\nfrom typing import Any, Dict\ntry:\n    from buster.experience.engine import ExperienceEngine\nexcept Exception:\n    ExperienceEngine = None  # type: ignore\n\nclass ExperienceDashboard:\n    """Backend model for showing experience stats in Mission Control."""\n    def __init__(self, data_dir: str = "data") -> None:\n        self.engine = ExperienceEngine(data_dir) if ExperienceEngine else None\n    def snapshot(self) -> Dict[str, Any]:\n        if not self.engine:\n            return {"available": False, "records": 0, "top_skills": []}\n        data = self.engine.summary()\n        data["available"] = True\n        data["title"] = "Experience Engine"\n        return data\n'}
DATA_DEFAULTS: Dict[str, Any] = {
    "data/experience_memory.json": [],
    "data/skill_profiles.json": {},
    "data/project_experience_index.json": {"projects": {}, "types": {}},
    "data/user_overrides.json": [],
}

def write_file(rel_path: str, content: str) -> None:
    path = ROOT / rel_path
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        backup = path.with_suffix(path.suffix + ".bak_v38")
        if not backup.exists(): shutil.copy2(path, backup)
    path.write_text(content, encoding="utf-8")
    print(f"[WRITE] {rel_path}")

def create_json_if_missing(rel_path: str, default: Any) -> None:
    path = ROOT / rel_path
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        path.write_text(json.dumps(default, indent=2), encoding="utf-8")
        print(f"[CREATE] {rel_path}")
    else:
        print(f"[KEEP] {rel_path}")

def main() -> None:
    print("=== Applying Buster v3.8 Experience Engine Patch ===")
    for rel_path, content in FILES.items(): write_file(rel_path, content)
    for rel_path, default in DATA_DEFAULTS.items(): create_json_if_missing(rel_path, default)
    print("\nSUCCESS: Buster v3.8 Experience Engine installed.")
    print("Next: python test_v3_8_experience_engine.py")
if __name__ == "__main__": main()
